import { ReactNode } from "react";
import { TrendUpIcon, TrendDownIcon } from "@/components/icons";
import { Skeleton } from "@/components/Skeleton";

type Trend = "up" | "down" | "neutral";

interface MetricCardProps {
  title: string;
  value: number | string;
  trend?: Trend;
  trendValue?: string;
  icon?: ReactNode;
  className?: string;
  loading?: boolean;
}

