    teamSize: 4,
  },
  {
    id: "p4",
    name: "Soporte Tier 1",
    type: "support",
    status: "blue" as const,
    progress: 90,
    start: "2026-01-01",
    end: "2026-12-31",
    tasksTotal: 120,
    tasksDone: 108,
    teamSize: 2,
  },
];

function ProgressBar({ value }: { value: number }) {
  const color =
    value >= 70
      ? "bg-green-500"
      : value >= 40
      ? "bg-yellow-400"
      : "bg-red-500";
  return (
    <div className="h-1.5 w-full rounded-full bg-slate-100">
      <div
        className={`h-1.5 rounded-full transition-all ${color}`}
        style={{ width: `${value}%` }}
      />
    </div>
  );
}

