@tailwind base;
@tailwind components;
@tailwind utilities;

/* ── Executive design tokens ──────────────────────────────────────────────── */
:root {
  /* Brand palette — primary blues */
  --color-brand-50:  #eff6ff;
  --color-brand-100: #dbeafe;
  --color-brand-500: #3b82f6;
  --color-brand-600: #2563eb;
  --color-brand-700: #1d4ed8;
  --color-brand-900: #1e3a5f;

  /* Traffic-light status colours */
  --color-status-green:  #22c55e;
  --color-status-yellow: #eab308;
  --color-status-red:    #ef4444;
  --color-status-blue:   #3b82f6;

  /* Surface palette */
  --color-surface-bg:     #f8fafc;
  --color-surface-card:   #ffffff;
  --color-surface-border: #e2e8f0;

  /* Sidebar */
  --color-sidebar-bg:      #1e293b;
  --color-sidebar-border:  #334155;
  --color-sidebar-active:  #2563eb;

  /* Typography scale */
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", Consolas, monospace;

  /* Shadows */
  --shadow-card: 0 1px 3px 0 rgb(0 0 0 / 0.08), 0 1px 2px -1px rgb(0 0 0 / 0.06);
  --shadow-card-hover: 0 4px 12px 0 rgb(0 0 0 / 0.10), 0 2px 4px -1px rgb(0 0 0 / 0.06);
}

/* ── Base reset ───────────────────────────────────────────────────────────── */
html,
body {
  @apply antialiased;
  background-color: var(--color-surface-bg);
  color: #0f172a;
  font-family: var(--font-sans);
}

/* Smooth scrolling */
* {
  scroll-behavior: smooth;
}

/* ── Date input browser-quirk fixes ─────────────────────────────────────── */
input[type="date"]::-webkit-calendar-picker-indicator {
  opacity: 0.5;
  cursor: pointer;
}

/* ── Scrollbar styling ───────────────────────────────────────────────────── */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 999px;
}
::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

/* ── Component layer ─────────────────────────────────────────────────────── */
@layer components {
  /* Generic card */
  .card {
    @apply rounded-xl border border-slate-200 bg-white p-6;
    box-shadow: var(--shadow-card);
  }
  .card:hover {
    box-shadow: var(--shadow-card-hover);
  }

  /* KPI number typography */
  .kpi-value {
    @apply text-4xl font-bold tabular-nums tracking-tight text-slate-900;
  }
  .kpi-label {
    @apply text-sm font-medium text-slate-500;
  }

  /* Status badge variants (used by StatusBadge component) */
  .status-badge-green {
    @apply inline-flex items-center gap-1.5 rounded-full border border-green-200 bg-green-50 px-2.5 py-0.5 text-xs font-medium text-green-700;
  }
  .status-badge-yellow {
    @apply inline-flex items-center gap-1.5 rounded-full border border-yellow-200 bg-yellow-50 px-2.5 py-0.5 text-xs font-medium text-yellow-700;
  }
  .status-badge-red {
    @apply inline-flex items-center gap-1.5 rounded-full border border-red-200 bg-red-50 px-2.5 py-0.5 text-xs font-medium text-red-700;
  }
  .status-badge-blue {
    @apply inline-flex items-center gap-1.5 rounded-full border border-blue-200 bg-blue-50 px-2.5 py-0.5 text-xs font-medium text-blue-700;
  }

  /* Sidebar nav item */
  .nav-item {
