      story_points: 0,
      tasks_completed: 0,
      tasks_assigned: 0,
      priority_avg: 0,
      relative_effort: 0,
      github_username: g.username,
      prs_merged: g.prs_merged,
      commits: g.commits_total,
      lines_net: g.lines_net,
    });
  }

  return result;
}

