import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { useDateRange } from "@/contexts/DateRangeContext";
import {
  PlaneTeamMetricsResponse,
  GitHubTeamMetricsResponse,
  PlaneProjectsResponse,
  UnifiedMember,
  TeamKPIs,
  TrendInfo,
} from "@/types/overview";

// ── Helpers ─────────────────────────────────────────────────────────────────

function getInitials(name: string): string {
  return name
    .split(" ")
    .map((part) => part.charAt(0).toUpperCase())
    .slice(0, 2)
    .join("");
}

function computeTrend(current: number, previous: number): TrendInfo {
  if (previous === 0 && current === 0) {
    return { direction: "neutral", label: "sin cambio" };
  }
  if (previous === 0) {
    return { direction: "up", label: `+${current}` };
  }
  const pct = Math.round(((current - previous) / previous) * 100);
  if (pct > 0) {
    return { direction: "up", label: `+${pct}% vs anterior` };
  }
  if (pct < 0) {
    return { direction: "down", label: `${pct}% vs anterior` };
  }
  return { direction: "neutral", label: "sin cambio" };
}

// ── API hooks ───────────────────────────────────────────────────────────────

export function usePlaneTeamMetrics() {
  return useQuery<PlaneTeamMetricsResponse>({
    queryKey: ["plane", "team-metrics"],
    queryFn: () =>
      api.get<PlaneTeamMetricsResponse>("/api/plane/team-metrics"),
    staleTime: 4 * 60 * 1000,
    refetchInterval: 5 * 60 * 1000,
  });
}

export function useGitHubTeamMetrics() {
  const { dateRange } = useDateRange();
  const from = dateRange.from.toISOString().slice(0, 10);
  const to = dateRange.to.toISOString().slice(0, 10);

  return useQuery<GitHubTeamMetricsResponse>({
    queryKey: ["github", "team-metrics", from, to],
    queryFn: () =>
      api.get<GitHubTeamMetricsResponse>(
        `/api/github/team-metrics?from=${from}&to=${to}`,
      ),
    staleTime: 4 * 60 * 1000,
    refetchInterval: 5 * 60 * 1000,
  });
}

export function usePlaneProjects() {
  return useQuery<PlaneProjectsResponse>({
    queryKey: ["plane", "projects"],
    queryFn: () =>
      api.get<PlaneProjectsResponse>("/api/plane/projects"),
    staleTime: 4 * 60 * 1000,
    refetchInterval: 5 * 60 * 1000,
  });
}

// ── Previous-period API hooks (for trend calculation) ───────────────────────

function usePreviousPlanTeamMetrics() {
  const { dateRange } = useDateRange();
  const rangeDays =
    Math.ceil(
      (dateRange.to.getTime() - dateRange.from.getTime()) / (1000 * 60 * 60 * 24),
    ) || 30;

  const prevTo = new Date(dateRange.from);
  prevTo.setDate(prevTo.getDate() - 1);
  const prevFrom = new Date(prevTo);
  prevFrom.setDate(prevFrom.getDate() - rangeDays);

  // We don't have a date-range filter on Plane team-metrics,
  // so we return null to signal no previous period is available.
  // Trend will default to "neutral" when previous data is absent.
  return { data: null as PlaneTeamMetricsResponse | null };
}

function usePreviousGitHubTeamMetrics() {
  const { dateRange } = useDateRange();
  const rangeDays =
    Math.ceil(
      (dateRange.to.getTime() - dateRange.from.getTime()) / (1000 * 60 * 60 * 24),
    ) || 30;

  const prevTo = new Date(dateRange.from);
  prevTo.setDate(prevTo.getDate() - 1);
  const prevFrom = new Date(prevTo);
  prevFrom.setDate(prevFrom.getDate() - rangeDays);

  const from = prevFrom.toISOString().slice(0, 10);
  const to = prevTo.toISOString().slice(0, 10);

  return useQuery<GitHubTeamMetricsResponse>({
    queryKey: ["github", "team-metrics", "prev", from, to],
    queryFn: () =>
      api.get<GitHubTeamMetricsResponse>(
        `/api/github/team-metrics?from=${from}&to=${to}`,
      ),
    staleTime: 10 * 60 * 1000,
    refetchInterval: 10 * 60 * 1000,
  });
}

// ── Unified hook ────────────────────────────────────────────────────────────

interface UseTeamOverviewResult {
  members: UnifiedMember[];
  kpis: TeamKPIs;
  trends: {
    tasks: TrendInfo;
    points: TrendInfo;
    prs: TrendInfo;
    projects: TrendInfo;
  };
  isLoading: boolean;
  isError: boolean;
}

export function useTeamOverview(): UseTeamOverviewResult {
  const planeQuery = usePlaneTeamMetrics();
  const githubQuery = useGitHubTeamMetrics();
  const projectsQuery = usePlaneProjects();
  const prevPlane = usePreviousPlanTeamMetrics();
  const prevGithub = usePreviousGitHubTeamMetrics();

  const isLoading =
    planeQuery.isLoading || githubQuery.isLoading || projectsQuery.isLoading;
  const isError =
    planeQuery.isError && githubQuery.isError;

  const planeData = planeQuery.data;
  const githubData = githubQuery.data;
  const projectsData = projectsQuery.data;

  // Merge Plane and GitHub members into unified list
  const members: UnifiedMember[] = [];

  if (planeData) {
    for (const pm of planeData.members) {
      // Find matching GitHub member by plane_member_id
      const gm = githubData?.members.find(
        (g) => g.plane_member_id === pm.member_id,
      );

      members.push({
        id: pm.member_id,
        name: pm.name,
        avatar_url: pm.avatar_url,
        initials: getInitials(pm.name),
        story_points: pm.story_points_completed,
        tasks_completed: pm.tasks_completed,
        tasks_assigned: pm.tasks_assigned,
        priority_avg: pm.priority_avg,
        relative_effort: pm.relative_effort,
        github_username: gm?.username ?? null,
        prs_open: gm?.prs_open ?? 0,
        prs_merged: gm?.prs_merged ?? 0,
        prs_rejected: gm?.prs_rejected ?? 0,
        commits: gm?.commits_total ?? 0,
        lines_added: gm?.lines_added ?? 0,
        lines_removed: gm?.lines_removed ?? 0,
        lines_net: gm?.lines_net ?? 0,
      });
    }
  }

  // Add GitHub-only members not linked to Plane
  if (githubData) {
    for (const gm of githubData.members) {
      const alreadyAdded = members.some(
        (m) => m.github_username === gm.username,
      );
      if (!alreadyAdded) {
        members.push({
          id: gm.username,
          name: gm.name ?? gm.username,
          avatar_url: gm.avatar_url,
          initials: getInitials(gm.name ?? gm.username),
          story_points: 0,
          tasks_completed: 0,
          tasks_assigned: 0,
          priority_avg: 0,
          relative_effort: 0,
          github_username: gm.username,
          prs_open: gm.prs_open,
          prs_merged: gm.prs_merged,
          prs_rejected: gm.prs_rejected,
          commits: gm.commits_total,
          lines_added: gm.lines_added,
          lines_removed: gm.lines_removed,
          lines_net: gm.lines_net,
        });
      }
    }
  }

  // Sort by story points descending
  members.sort((a, b) => b.story_points - a.story_points);

  // Compute KPIs
  const totalTasksCompleted =
    planeData?.total_tasks_completed ??
    members.reduce((sum, m) => sum + m.tasks_completed, 0);

  const totalStoryPoints =
    planeData?.total_story_points ??
    members.reduce((sum, m) => sum + m.story_points, 0);

  const avgStoryPoints =
    members.length > 0
      ? Math.round((totalStoryPoints / members.length) * 10) / 10
      : 0;

  const totalPrsMerged = members.reduce((sum, m) => sum + m.prs_merged, 0);

  const activeProjects =
    projectsData?.projects.filter(
      (p) => p.status !== "red",
    ).length ?? 0;

  const kpis: TeamKPIs = {
    totalTasksCompleted,
    avgStoryPoints,
    totalPrsMerged,
    activeProjects,
  };

  // Compute trends (previous period comparison)
  const prevPlaneTasks = prevPlane.data?.total_tasks_completed ?? 0;
  const prevPlanePoints = prevPlane.data?.total_story_points ?? 0;
  const prevGithubPrs =
    prevGithub.data?.members.reduce((s, m) => s + m.prs_merged, 0) ?? 0;

  const trends = {
    tasks: prevPlaneTasks > 0
      ? computeTrend(totalTasksCompleted, prevPlaneTasks)
      : { direction: "neutral" as const, label: "período actual" },
    points: prevPlanePoints > 0
      ? computeTrend(totalStoryPoints, prevPlanePoints)
      : { direction: "neutral" as const, label: "período actual" },
    prs: prevGithubPrs > 0
      ? computeTrend(totalPrsMerged, prevGithubPrs)
      : { direction: "neutral" as const, label: "período actual" },
    projects: {
      direction: "neutral" as const,
      label: `${activeProjects} activos`,
    },
  };

  return { members, kpis, trends, isLoading, isError };
}

