              <XAxis dataKey="metric" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} />
              <Tooltip
                content={
                  <GroupedBarTooltip memberNames={memberNames} />
                }
              />
              <Legend
                wrapperStyle={{ fontSize: 12 }}
